    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.decorView.systemUiVisibility = View.SYSTEM_UI_FLAG_FULLSCREEN or View.SYSTEM_UI_FLAG_HIDE_NAVIGATION or View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
        dark=prefs.getBoolean("dark",false); collapsed=prefs.getBoolean("collapsed",false)
        val root=FrameLayout(this); setContentView(root); web=WebView(this); root.addView(web,FrameLayout.LayoutParams(-1,-1)); configureWebView(); showHome()
    }
    private fun configureWebView(){
        WebView.setWebContentsDebuggingEnabled(true); web.setBackgroundColor(Color.BLACK)
        web.settings.apply{javaScriptEnabled=true;domStorageEnabled=true;databaseEnabled=true;mediaPlaybackRequiresUserGesture=false;useWideViewPort=true;loadWithOverviewMode=true;setSupportZoom(false);mixedContentMode=WebSettings.MIXED_CONTENT_COMPATIBILITY_MODE;cacheMode=WebSettings.LOAD_DEFAULT;userAgentString="Mozilla/5.0 (Linux; Android 12; C16) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36"}
        CookieManager.getInstance().apply{setAcceptCookie(true);setAcceptThirdPartyCookies(web,true)}
        web.webChromeClient=WebChromeClient(); web.webViewClient=object:WebViewClient(){override fun shouldOverrideUrlLoading(view:WebView?,request:WebResourceRequest?):Boolean{val u=request?.url?:return false;if(u.scheme=="c16"){route(u);return true};return false}}
    }
    private fun route(u:Uri){when(u.host){"home"->showHome();"watch"->showPlayer(u.getQueryParameter("id").orEmpty());"category"->showCategory(u.getQueryParameter("name").orEmpty());"search"->showSearch(u.getQueryParameter("q").orEmpty());"theme"->{dark=!dark;prefs.edit().putBoolean("dark",dark).apply();rerender()};"sidebar"->{collapsed=!collapsed;prefs.edit().putBoolean("collapsed",collapsed).apply();rerender()};"history"->showSimple("历史记录","这里会显示在车机内打开过的视频。");"favorites"->showSimple("我的收藏","收藏的视频会集中显示在这里。");"subscriptions"->showSimple("订阅","登录后显示订阅频道更新。");"local"->showSimple("本地视频","后续可接入车机本地媒体库。");"settings"->showSimple("设置","C16 YouTube · V4.3 播放兼容性修复版");"login"->showSimple("YouTube 登录","手机授权入口将在下一步继续接回现有 OAuth 登录模块。")}}
    private fun rerender(){currentVideoId?.let{showPlayer(it)}?:showHome()}
    private fun load(html:String){web.loadDataWithBaseURL("https://www.youtube.com/",html,"text/html","UTF-8",null)}
    private fun svg(n:String)=when(n){"home"->"<svg viewBox='0 0 24 24'><path d='M3 11.2 12 4l9 7.2v8.3a1.5 1.5 0 0 1-1.5 1.5h-5v-6h-5v6h-5A1.5 1.5 0 0 1 3 19.5z'/></svg>";"drive"->"<svg viewBox='0 0 24 24'><path d='M5 16h14l-1.4-5.1A2.5 2.5 0 0 0 15.2 9H8.8a2.5 2.5 0 0 0-2.4 1.9zM4 16v3m16-3v3M7 13h.01M17 13h.01'/></svg>";"search"->"<svg viewBox='0 0 24 24'><circle cx='10.5' cy='10.5' r='6.5'/><path d='m15.5 15.5 5 5'/></svg>";"sub"->"<svg viewBox='0 0 24 24'><rect x='3' y='6' width='18' height='13' rx='3'/><path d='m10 10 5 3-5 3z'/></svg>";"history"->"<svg viewBox='0 0 24 24'><circle cx='12' cy='12' r='8.5'/><path d='M12 7v5l3.5 2'/></svg>";"heart"->"<svg viewBox='0 0 24 24'><path d='M20.8 5.8a5.2 5.2 0 0 0-7.4 0L12 7.2l-1.4-1.4a5.2 5.2 0 0 0-7.4 7.4L12 22l8.8-8.8a5.2 5.2 0 0 0 0-7.4z'/></svg>";"local"->"<svg viewBox='0 0 24 24'><rect x='3' y='5' width='18' height='14' rx='3'/><path d='m10 9 5 3-5 3z'/></svg>";else->"<svg viewBox='0 0 24 24'><circle cx='12' cy='12' r='3'/><path d='M12 2v3m0 14v3M2 12h3m14 0h3M4.9 4.9 7 7m10 10 2.1 2.1M19.1 4.9 17 7M7 17l-2.1 2.1'/></svg>"}
    private fun shell(active:String,body:String,player:Boolean=false):String{
        val bg=if(dark)"#0f0f0f" else "#f7f8fa";val side=if(dark)"#151515" else "#fff";val panel=if(dark)"#181818" else "#fff";val p2=if(dark)"#272727" else "#eef0f3";val text=if(dark)"#f5f5f5" else "#161616";val sub=if(dark)"#aaa" else "#737982";val border=if(dark)"#2d2d2d" else "#e2e5e9";val activeBg=if(dark)"#5a252c" else "#ffdce0";val c=player||collapsed;val sideW=if(c)"104px" else "260px";fun nav(id:String,icon:String,label:String,host:String)="<a class='nav ${if(active==id)"on" else ""}' href='c16://$host'><span class='navIcon'>${svg(icon)}</span><b>$label</b></a>";val menu=if(c)"›" else "‹"
        return """<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no'><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:$bg;color:$text;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI','Noto Sans SC','PingFang SC',Arial,sans-serif}a{text-decoration:none;color:inherit}.app{height:100vh;display:grid;grid-template-columns:$sideW 1fr}.sidebar{position:relative;background:$side;border-right:1px solid $border;padding:22px ${if(c)"14px" else "20px"};display:flex;flex-direction:column}.brand{height:66px;display:flex;align-items:center;gap:13px;margin-bottom:20px;justify-content:${if(c)"center" else "flex-start"}}.ytLogo{width:56px;height:38px;border-radius:11px;background:#ff0033;color:#fff;display:flex;align-items:center;justify-content:center;font-size:20px}.brand strong{font-size:31px;${if(c)"display:none" else ""}}.nav{height:62px;border-radius:17px;display:flex;align-items:center;gap:16px;padding:0 ${if(c)"20px" else "18px"};margin:3px 0;font-size:21px;justify-content:${if(c)"center" else "flex-start"}}.navIcon{width:28px;height:28px;display:flex}.navIcon svg{width:28px;height:28px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}.nav b{font-weight:680;${if(c)"display:none" else ""}}.nav.on{background:$activeBg}.collapse{position:absolute;right:-18px;top:47%;width:38px;height:72px;border-radius:0 20px 20px 0;background:$panel;border:1px solid $border;border-left:0;display:flex;align-items:center;justify-content:center;font-size:32px;z-index:30;box-shadow:0 6px 20px rgba(0,0,0,.12)}.main{min-width:0;display:grid;grid-template-rows:90px 1fr}.top{display:flex;align-items:center;padding:14px 28px;gap:12px;border-bottom:1px solid $border;background:$side}.search{height:56px;width:min(56%,900px);margin-left:auto;background:$p2;border:1px solid $border;border-radius:29px;display:flex;align-items:center;padding:0 18px}.search input{flex:1;border:0;outline:0;background:transparent;color:$text;font-size:20px}.search button{border:0;background:transparent;color:$text;font-size:23px}.pill{height:50px;border-radius:25px;padding:0 18px;border:1px solid $border;background:$panel;display:flex;align-items:center;font-size:18px;font-weight:800}.round{width:50px;height:50px;border-radius:50%;border:1px solid $border;background:$panel;display:flex;align-items:center;justify-content:center;font-size:22px}.content{min-height:0;overflow-y:auto;overflow-x:hidden;padding:20px 28px 80px;scroll-behavior:smooth}.content::-webkit-scrollbar{width:8px}.content::-webkit-scrollbar-thumb{background:${if(dark)"#444" else "#c7cbd0"};border-radius:8px}.chips{display:flex;gap:9px;margin-bottom:16px}.chip{padding:10px 18px;border-radius:20px;background:$panel;border:1px solid $border;font-size:17px;font-weight:750}.chip.on{background:$text;color:$bg}.hero{height:330px;border-radius:27px;overflow:hidden;position:relative;background:#111;border:1px solid $border}.hero img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(4,8,14,.94),rgba(4,8,14,.70) 38%,rgba(4,8,14,.08) 72%)}.heroCopy{position:absolute;z-index:2;left:40px;top:32px;width:47%;color:#fff}.heroCopy small{color:#72c7ff;font-weight:900;letter-spacing:3px}.heroCopy h1{font-size:45px;line-height:1.08;margin:10px 0 12px}.heroCopy p{font-size:18px;color:#eee}.heroBtns{display:flex;gap:10px;margin-top:20px}.btn{padding:11px 20px;border-radius:22px;background:#fff;color:#111;font-size:18px;font-weight:850}.btn.alt{background:rgba(255,255,255,.16);color:#fff;border:1px solid rgba(255,255,255,.3)}.section{margin-top:28px}.sectionHead{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.sectionHead h2{font-size:31px;margin:0}.sectionHead span{color:$sub;font-size:16px}.railWrap{position:relative}.rail{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 64px)/5);gap:16px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:8px}.rail::-webkit-scrollbar{display:none}.card{scroll-snap-align:start;min-width:0}.thumb{aspect-ratio:16/9;border-radius:15px;overflow:hidden;background:#161616;border:1px solid $border}.thumb img{width:100%;height:100%;object-fit:cover;display:block}.ctitle{font-size:18px;font-weight:800;line-height:1.3;margin-top:8px;height:48px;overflow:hidden}.cmeta{font-size:14px;color:$sub;line-height:1.4}.arrow{position:absolute;right:10px;top:31%;z-index:5;width:54px;height:54px;border-radius:50%;background:$panel;border:1px solid $border;box-shadow:0 6px 20px rgba(0,0,0,.18);font-size:30px;color:$text}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px 18px}.playerLayout{display:grid;grid-template-columns:minmax(0,1fr) 420px;gap:24px}.playerBox{position:relative;aspect-ratio:16/9;background:#061d2b;border-radius:20px;overflow:hidden;border:1px solid $border}.playerBox iframe{width:100%;height:100%;border:0;display:block;position:relative;z-index:1}.loading{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;color:#fff;background:linear-gradient(135deg,#061d2b,#07334a);z-index:0}.spinner{width:58px;height:58px;border-radius:50%;border:5px solid rgba(255,255,255,.28);border-top-color:#ff0033;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.pTitle{font-size:40px;font-weight:900;line-height:1.18;margin:16px 0 8px}.pMeta{font-size:19px;color:$sub}.channel{display:flex;align-items:center;gap:14px;padding:17px 0;border-top:1px solid $border;border-bottom:1px solid $border;margin-top:17px}.avatar{width:62px;height:62px;border-radius:50%;background:linear-gradient(135deg,#3aa2ff,#1758a2)}.channelText{flex:1}.channelText b{display:block;font-size:25px}.channelText span{color:$sub;font-size:16px}.subscribe{padding:12px 22px;border-radius:24px;background:$text;color:$bg;font-weight:850;font-size:18px}.actions{display:flex;gap:9px;margin-top:14px;flex-wrap:wrap}.action{padding:10px 16px;border-radius:21px;background:$panel;border:1px solid $border;font-size:17px;font-weight:750}.recommend{background:$panel;border:1px solid $border;border-radius:20px;padding:14px;max-height:calc(100vh - 130px);overflow-y:auto}.recTabs{display:flex;gap:8px;position:sticky;top:0;background:$panel;padding-bottom:12px;z-index:2}.tab{padding:9px 13px;border-radius:18px;background:$p2;font-size:15px;font-weight:750}.tab.on{background:$text;color:$bg}.rec{display:grid;grid-template-columns:154px 1fr;gap:11px;margin-bottom:14px}.rec img{width:154px;aspect-ratio:16/9;object-fit:cover;border-radius:10px}.rec b{font-size:16px;line-height:1.28;display:block}.rec span{font-size:13px;color:$sub}.comments{margin-top:20px;padding:20px;background:$panel;border:1px solid $border;border-radius:18px}.comments h2{margin:0 0 12px;font-size:27px}.comment{display:flex;gap:12px;padding:13px 0;border-top:1px solid $border}.commentAvatar{width:42px;height:42px;border-radius:50%;background:$p2}.comment p{font-size:16px;line-height:1.5;margin:4px 0}.simple{background:$panel;border:1px solid $border;border-radius:22px;padding:32px}.simple h1{font-size:36px;margin-top:0}.simple p{font-size:20px;color:$sub}
</style></head><body><div class='app'><aside class='sidebar'><div class='brand'><div class='ytLogo'>▶</div><strong>YouTube</strong></div>${nav("home","home","首页","home")}${nav("drive","drive","驾驶模式","home")}${nav("search","search","探索","search?q=")}${nav("sub","sub","订阅","subscriptions")}${nav("history","history","历史记录","history")}${nav("favorites","heart","我的收藏","favorites")}${nav("local","local","本地视频","local")}${nav("settings","settings","设置","settings")}<a class='collapse' href='c16://sidebar'>$menu</a></aside><main class='main'><header class='top'><form class='search' action='c16://search'><input name='q' placeholder='搜索 YouTube'><button>⌕</button></form><a class='pill' href='c16://login'>登录</a><a class='round' href='c16://favorites'>♡</a><a class='round' href='c16://theme'>${if(dark)"☀" else "☾"}</a></header><section class='content'>$body</section></main></div></body></html>"""
    }
    private fun thumb(v:Video)="https://i.ytimg.com/vi/${v.id}/hqdefault.jpg"
    private fun card(v:Video)="<a class='card' href='c16://watch?id=${v.id}'><div class='thumb'><img src='${thumb(v)}'></div><div class='ctitle'>${esc(v.title)}</div><div class='cmeta'>${esc(v.channel)}<br>${esc(v.meta)}</div></a>"
    private fun chips(active:String)=listOf("推荐","科技AI","汽车","音乐","旅行","电影","哲学").joinToString(""){"<a class='chip ${if(it==active)"on" else ""}' href='c16://category?name=${Uri.encode(it)}'>$it</a>"}
    private fun rail(title:String,note:String,list:List<Video>)="<div class='section'><div class='sectionHead'><h2>$title</h2><span>$note</span></div><div class='railWrap'><div class='rail'>${list.joinToString(""){card(it)}}</div><button class='arrow' onclick=\"this.previousElementSibling.scrollBy({left:900,behavior:'smooth'})\">›</button></div></div>"
    private fun showHome(){currentVideoId=null;val hero=videos.first();val body="""<div class='chips'>${chips("推荐")}</div><div class='hero'><img src='${thumb(hero)}'><div class='shade'></div><div class='heroCopy'><small>为你精选</small><h1>${esc(hero.title)}</h1><p>来自你的观看、订阅与近期内容。</p><div class='heroBtns'><a class='btn' href='c16://watch?id=${hero.id}'>▶ 立即播放</a><a class='btn alt' href='c16://category?name=科技AI'>探索更多</a></div></div></div>${rail("继续观看","你的车机观看记录",videos.take(8))}${rail("订阅频道更新","来自你订阅的频道",videos.drop(3).take(9))}${rail("猜你喜欢","向右查看更多",videos.reversed())}<div style='height:30px'></div>""";load(shell("home",body))}
    private fun showCategory(name:String){currentVideoId=null;val list=if(name=="推荐")videos else videos.filter{it.category==name || (name=="科技AI"&&it.category=="科技")};val body="<div class='chips'>${chips(name)}</div><div class='sectionHead'><h2>${esc(name)}</h2><span>${list.size} 个视频</span></div><div class='grid'>${list.joinToString(""){card(it)}}</div>";load(shell("home",body))}
    private fun showSearch(q:String){currentVideoId=null;val list=if(q.isBlank())videos else videos.filter{it.title.contains(q,true)||it.channel.contains(q,true)||it.category.contains(q,true)};val body="<div class='sectionHead'><h2>搜索${if(q.isBlank())"" else "：${esc(q)}"}</h2><span>${list.size} 个结果</span></div><div class='grid'>${list.joinToString(""){card(it)}}</div>";load(shell("search",body))}
    private fun showPlayer(id:String){
        val v=videos.firstOrNull{it.id==id}?:Video(id,"YouTube 视频","YouTube","正在播放","推荐");currentVideoId=id
        val same=videos.filter{it.id!=id&&it.channel==v.channel};val related=videos.filter{it.id!=id&&it.category==v.category&&it !in same}+videos.filter{it.id!=id&&it !in same&&it.category!=v.category};val recs=(same+related).distinctBy{it.id}.take(12)
        val recHtml=recs.joinToString(""){r->"<a class='rec' href='c16://watch?id=${r.id}'><img src='${thumb(r)}'><div><b>${esc(r.title)}</b><span>${esc(r.channel)}<br>${esc(r.meta)}</span></div></a>"}
        val embed="https://www.youtube.com/embed/${Uri.encode(id)}?autoplay=1&playsinline=1&rel=0&modestbranding=1&enablejsapi=1&origin=https%3A%2F%2Fwww.youtube.com"
        val comments="<div class='comments'><h2>评论</h2><div class='comment'><div class='commentAvatar'></div><div><b>C16 YouTube</b><p>评论区保留；真实评论仍需 YouTube Data API 对应权限，未授权时不伪造评论数据。</p></div></div></div>"
        val body="""<div class='playerLayout'><div><div class='playerBox'><div class='loading'><div class='spinner'></div><b style='font-size:22px'>正在准备 YouTube 播放器</b><span>如果仍无法播放，请检查代理与 YouTube 登录状态</span></div><iframe src='$embed' allow='autoplay; encrypted-media; picture-in-picture; fullscreen' allowfullscreen referrerpolicy='strict-origin-when-cross-origin'></iframe></div><div class='pTitle'>${esc(v.title)}</div><div class='pMeta'>${esc(v.meta)}</div><div class='channel'><div class='avatar'></div><a class='channelText' href='c16://category?name=${Uri.encode(v.category)}'><b>${esc(v.channel)}</b><span>点击查看更多相关内容</span></a><a class='subscribe' href='c16://subscriptions'>订阅</a></div><div class='actions'><a class='action' href='c16://favorites'>♡ 收藏</a><a class='action' href='c16://category?name=${Uri.encode(v.category)}'>▤ 推荐</a><a class='action' href='c16://sidebar'>☰ 侧栏</a></div>$comments</div><aside class='recommend'><div class='recTabs'><span class='tab on'>同作者优先</span><span class='tab'>相关推荐</span></div>$recHtml</aside></div>""";load(shell("",body,true))
    }
    private fun showSimple(title:String,copy:String){currentVideoId=null;load(shell("","<div class='simple'><h1>${esc(title)}</h1><p>${esc(copy)}</p><a class='chip' href='c16://home'>返回首页</a></div>"))}
    private fun esc(s:String)=s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;")
}
